use vstd::prelude::*;

verus! {

fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> (ret: Vec<Vec<String>>)
    requires
        sep.len() > 0,
    ensures
        ret.len() == a.len(),
    ensures
        forall |i: usize| i < ret.len() ==> ret[i].len() >= 1,
    ensures
        maxsplit == 0 ==>
            forall |i: usize|
                i < ret.len() ==>
                    ret[i].len() == 1 && ret[i][0] == a[i],
    ensures
        forall |i: usize| i < a.len() ==> ret[i].len() <= (maxsplit as usize) + 1,
    ensures
        forall |i: usize|
            i < a.len() && a[i].len() == 0 ==>
                ret[i].len() == 1 && ret[i][0].len() == 0,
{
    let mut ret: Vec<Vec<String>> = Vec::new();
    let n = a.len();
    let max = maxsplit as usize;
    let mut i: usize = 0;
    // Process each string in `a`
    while i < n
        invariant
            i <= n,
            ret.len() == i,
            // so far ret satisfies the per-element properties
            forall |j: usize| j < ret.len() ==> ret[j].len() >= 1,
            forall |j: usize| j < ret.len() && maxsplit == 0 ==> ret[j].len() == 1 && ret[j][0] == a[j],
            forall |j: usize| j < i ==> ret[j].len() <= max + 1,
            forall |j: usize| j < i && a[j].len() == 0 ==> ret[j].len() == 1 && ret[j][0].len() == 0,
        decreases
            n - i,
    {
        let s = a[i].clone();
        if max == 0 {
            // No splitting requested
            let mut parts: Vec<String> = Vec::new();
            parts.push(s.clone());
            // parts.len() == 1
            assert(parts.len() == 1);
            ret.push(parts);
        } else {
            // Perform up to `max` right-splits
            let mut parts: Vec<String> = Vec::new();
            let mut remaining = s.clone();
            let mut count: usize = 0;
            while count < max
                invariant
                    count <= max,
                    parts.len() <= count,
                decreases
                    max - count,
            {
                match remaining.rfind(&sep) {
                    Some(pos) => {
                        // sep.len() > 0, so pos+sep.len() <= remaining.len()
                        let slen = sep.len();
                        let suffix = remaining[(pos + slen)..].to_string();
                        parts.push(suffix);
                        // chop off the suffix and the separator
                        let prefix = remaining[..pos].to_string();
                        remaining = prefix;
                        count += 1;
                    }
                    None => {
                        break;
                    }
                }
            }
            // push whatever is left
            parts.push(remaining.clone());
            // reverse to get left-to-right order
            parts.reverse();
            // verify the required bounds
            assert(parts.len() >= 1);
            assert(parts.len() <= max + 1);
            ret.push(parts);
        }
        i += 1;
    }
    ret
}

} // verus!

